#!/usr/bin/env python3
# provenance: original
# Copyright (c) 2026 John Lipka and the Pelias contributors
"""Checks that Pelias's Unicode tables (generated by tools/gen_unicode_tables.py) agree with
the Hugging Face tokenizers library itself, code point by code point. Run inside the reference venv.

    python3 tools/hf_unicode_probe.py

For every code point (surrogates excepted) it asks the library's own regex engine whether the code point is \\p{L},
\\p{M}, \\p{N} or \\s and compares with Pelias's tables (read from src/tok/unicode_tables.cpp); then it asks the
library's NFC normalizer about each code point, each canonical decomposition and every combining mark against marks
of eight known classes, and compares with Pelias's NFC (its algorithm re-expressed here over the same tables).
Prints the counts and the first differing code points; exit 1 when anything differs (the generator then needs the
library's answers instead of Python's for those code points).
"""
import sys
import unicodedata


def main():
    import tokenizers
    from tokenizers import Regex, normalizers, pre_tokenizers
    print(f'tokenizers {tokenizers.__version__}; Python {sys.version.split()[0]} unicodedata {unicodedata.unidata_version}')

    cps = [c for c in range(0x110000) if not 0xD800 <= c <= 0xDFFF]
    text = ''.join(chr(c) for c in cps)
    import os
    import re
    src = open(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'src', 'tok', 'unicode_tables.cpp'),
               encoding='utf-8').read()
    print('Pelias tables: ' + src.splitlines()[0].split('from ', 1)[-1])

    def table(name):
        body = re.search(r'const CpRange ' + name + r'\[\] = \{(.*?)\n\};', src, re.S).group(1)
        out = set()
        for lo, hi in re.findall(r'\{0x([0-9A-F]+), 0x([0-9A-F]+)\}', body):
            out.update(range(int(lo, 16), int(hi, 16) + 1))
        return out

    tl, tm, tn, tw = table('kLetter'), table('kMark'), table('kNumber'), table('kWhiteSpace')
    python_class = {
        r'\p{L}': lambda c: c in tl,
        r'\p{M}': lambda c: c in tm,
        r'\p{N}': lambda c: c in tn,
        r'\s': lambda c: c in tw,
    }
    bad = 0
    for pattern, py in python_class.items():
        split = pre_tokenizers.Split(Regex(pattern), behavior='removed')
        pieces = split.pre_tokenize_str(text)
        to_char = None
        if pieces and max(e for _p, (_s, e) in pieces) > len(cps):  # byte offsets: map them to code point indices
            to_char = {}
            b = 0
            for k, c in enumerate(cps):
                to_char[b] = k
                b += len(chr(c).encode('utf-8'))
            to_char[b] = len(cps)
        kept = [False] * len(cps)
        for _piece, (start, end) in pieces:
            if to_char is not None:
                start, end = to_char[start], to_char[end]
            for k in range(start, end):
                kept[k] = True
        diffs = [c for k, c in enumerate(cps) if (not kept[k]) != py(c)]
        bad += len(diffs)
        show = ', '.join(f'U+{c:04X} (library says {"no" if py(c) else "yes"})' for c in diffs[:12])
        print(f'{pattern}: {len(diffs)} code points differ' + (f': {show}' if diffs else ''))

    # NFC: Pelias's own algorithm re-expressed in Python over the same generated tables (src/tok/unicode.cpp)
    def ints(name, n):
        body = re.search(r'const \w+ ' + name + r'\[\] = \{(.*?)\n\};', src, re.S).group(1)
        vals = [int(x, 16) for x in re.findall(r'0x([0-9A-F]+)', body)]
        if n == 1:
            return vals
        return [tuple(vals[k:k + n]) for k in range(0, len(vals), n)]

    ccc_t = {}
    body = re.search(r'const CccRange kCcc\[\] = \{(.*?)\n\};', src, re.S).group(1)
    for lo, hi, c in re.findall(r'\{0x([0-9A-F]+), 0x([0-9A-F]+), (\d+)\}', body):
        for cp in range(int(lo, 16), int(hi, 16) + 1):
            ccc_t[cp] = int(c)
    pool = ints('kDecompPool', 1)
    body = re.search(r'const DecompEntry kDecomp\[\] = \{(.*?)\n\};', src, re.S).group(1)
    dec_t = {int(cp, 16): pool[int(off):int(off) + int(ln)] for cp, off, ln in re.findall(r'\{0x([0-9A-F]+), (\d+), (\d+)\}', body)}
    comp_t = {(a, b): c for a, b, c in ints('kCompose', 3)}
    SB, LB, VB, TB, LC, VC, TC = 0xAC00, 0x1100, 0x1161, 0x11A7, 19, 21, 28
    NC, SC = VC * TC, LC * VC * TC

    def pel_nfc(text):
        buf = []
        for ch in text:
            cp = ord(ch)
            if SB <= cp < SB + SC:
                sidx = cp - SB
                buf += [LB + sidx // NC, VB + (sidx % NC) // TC] + ([TB + sidx % TC] if sidx % TC else [])
            else:
                buf += dec_t.get(cp, [cp])
        k = 0
        while k < len(buf):
            if ccc_t.get(buf[k], 0) == 0:
                k += 1
                continue
            e = k
            while e < len(buf) and ccc_t.get(buf[e], 0) != 0:
                e += 1
            buf[k:e] = sorted(buf[k:e], key=lambda x: ccc_t.get(x, 0))
            k = e
        if not buf:
            return ''

        def compose(a, b):
            if LB <= a < LB + LC and VB <= b < VB + VC:
                return SB + ((a - LB) * VC + (b - VB)) * TC
            if SB <= a < SB + SC and (a - SB) % TC == 0 and TB < b < TB + TC:
                return a + (b - TB)
            return comp_t.get((a, b), 0)
        sp, st = 0, buf[0]
        last = ccc_t.get(st, 0)
        if last:
            last = 256
        cpos = 1
        for k in range(1, len(buf)):
            ch = buf[k]
            cc = ccc_t.get(ch, 0)
            c = compose(st, ch)
            if c and (last < cc or last == 0):
                buf[sp] = c
                st = c
                continue
            if cc == 0:
                sp, st = cpos, ch
            last = cc
            buf[cpos] = ch
            cpos += 1
        return ''.join(chr(x) for x in buf[:cpos])

    nfc = normalizers.NFC()
    diffs = [c for c in cps if nfc.normalize_str(chr(c)) != pel_nfc(chr(c))]
    bad += len(diffs)
    print(f'NFC of single code points: {len(diffs)} differ' + (': ' + ', '.join(f'U+{c:04X}' for c in diffs[:12]) if diffs else ''))
    seqs = []
    for c in cps:
        d = unicodedata.normalize('NFD', chr(c))
        if d != chr(c):
            seqs.append(d)
            seqs.append(d + '\u0301')  # one more mark after it (reordering and blocking)
    # every mark (in either source) against reference marks of known classes 1, 7, 9, 202, 220, 230, 232, 240,
    # in both orders: any difference in a combining class shows up as a different order
    refs = ['\u0334', '\u093C', '\u094D', '\u0327', '\u0316', '\u0301', '\u0315', '\u0345']
    marks = sorted(set(ccc_t) | {c for c in cps if unicodedata.category(chr(c)).startswith('M')})
    for m in marks:
        for r in refs:
            seqs.append('a' + chr(m) + r)
            seqs.append('a' + r + chr(m))
    diffs = [x for x in seqs if nfc.normalize_str(x) != pel_nfc(x)]
    bad += len(diffs)
    print(f'NFC of {len(seqs)} test sequences (decompositions, and every mark against 8 reference classes): {len(diffs)} differ' +
          (': ' + ', '.join(' '.join(f'U+{ord(x):04X}' for x in sq) for sq in diffs[:8]) if diffs else ''))
    print('RESULT: ' + ('the tables agree with the library' if bad == 0 else f'{bad} differences'))
    return 1 if bad else 0


if __name__ == '__main__':
    sys.exit(main())
